<?php
/**
 * Property-Based Tests: Aggregate Payload Contains No PII
 *
 * **Validates: Requirements 4.5, 10.4**
 *
 * Property 4: For all payloads generated by AggregateExporter, no field
 * contains PII data (names, NIM, phone numbers, emails, borrowing history).
 *
 * Formal: ∀ payload ∈ generatedPayloads: extractFields(payload) ∩ PII_FIELDS == ∅
 *
 * This test simulates property-based testing by generating many random
 * combinations of inputs and verifying the property holds universally.
 *
 * Also covers Property 13 (PII Sanitization Completeness) for EnhancedExporter.
 *
 * @package NextLib\Agent\Tests
 */

namespace NextLib\Agent\Tests;

use PHPUnit\Framework\TestCase;
use NextLibAgent\Exporter\AggregateExporter;
use NextLibAgent\Exporter\EnhancedExporter;
use NextLibAgent\Exporter\MetricsCollector;
use NextLibAgent\Exporter\AnomalyTagger;
use NextLibAgent\Exporter\RetryScheduler;
use NextLibAgent\lib\HttpClient;
use PDO;

class PiiPropertyTest extends TestCase
{
    /**
     * @var PDO In-memory SQLite database
     */
    private $db;

    /**
     * @var HttpClient|\PHPUnit\Framework\MockObject\MockObject
     */
    private $httpClient;

    /**
     * Number of random iterations for property tests.
     */
    const ITERATIONS = 100;

    /**
     * Sample PII data used to inject and detect leaks.
     */
    const PII_EMAILS = array(
        'student@university.ac.id',
        'john.doe@gmail.com',
        'admin@univ.edu',
        'budi.santoso@campus.ac.id',
        'test+user@example.co.id',
    );

    const PII_PHONES = array(
        '+6281234567890',
        '08123456789',
        '0812 3456 7890',
        '+62-812-3456-7890',
        '021-555-12345',
    );

    const PII_NAMES = array(
        'Muhammad Rizky Pratama Putra',
        'Siti Nurhaliza Binti Ahmad',
        'John William Smith Junior',
        'Maria Christina Dewi Sartika',
        'Budi Setiawan Putra Utama',
    );

    const PII_NIMS = array(
        '20210001234',
        '19850012345',
        '2024567890123',
        '12345678',
        '20200099887',
    );

    protected function setUp(): void
    {
        $this->db = new PDO('sqlite::memory:');
        $this->db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        $this->db->exec("
            CREATE TABLE visitor_count (
                visitor_id INTEGER PRIMARY KEY AUTOINCREMENT,
                member_id VARCHAR(20),
                member_name VARCHAR(100),
                checkin_date DATETIME NOT NULL
            )
        ");

        $this->db->exec("
            CREATE TABLE loan (
                loan_id INTEGER PRIMARY KEY AUTOINCREMENT,
                member_id VARCHAR(20),
                item_code VARCHAR(20),
                loan_date DATE NOT NULL,
                due_date DATE,
                return_date DATE
            )
        ");

        $this->httpClient = $this->createMock(HttpClient::class);
    }

    // =========================================================================
    // Property 4: buildPayload() output never contains PII
    // =========================================================================

    /**
     * **Validates: Requirements 4.5, 10.4**
     *
     * Property: For all random stats combinations, buildPayload() output
     * never contains PII patterns regardless of input values.
     *
     * @dataProvider randomStatsProvider
     */
    public function testBuildPayloadNeverContainsPII(
        int $visitorCount,
        int $loanCount,
        int $returnCount,
        string $tenantId,
        string $date
    ): void {
        $config = array('tenant_id' => $tenantId, 'cloud_base_url' => 'https://cloud.nextlib.id');
        $exporter = new AggregateExporter($this->db, $this->httpClient, $config);

        $stats = array(
            'visitor_count' => $visitorCount,
            'loan_count' => $loanCount,
            'return_count' => $returnCount,
        );

        $payload = $exporter->buildPayload($stats, $date);

        $this->assertFalse(
            AggregateExporter::containsPII($payload),
            sprintf(
                "buildPayload() produced PII for stats=[%d,%d,%d], tenant_id='%s', date='%s'. Payload: %s",
                $visitorCount,
                $loanCount,
                $returnCount,
                $tenantId,
                $date,
                json_encode($payload)
            )
        );
    }

    /**
     * Data provider that generates random stats combinations.
     *
     * @return array[]
     */
    public function randomStatsProvider(): array
    {
        $cases = array();
        $tenantFormats = $this->generateTenantIds();
        $dates = $this->generateDates();

        for ($i = 0; $i < self::ITERATIONS; $i++) {
            $visitorCount = mt_rand(0, 10000);
            $loanCount = mt_rand(0, 10000);
            $returnCount = mt_rand(0, 10000);
            $tenantId = $tenantFormats[array_rand($tenantFormats)];
            $date = $dates[array_rand($dates)];

            $cases["iteration_$i"] = array($visitorCount, $loanCount, $returnCount, $tenantId, $date);
        }

        return $cases;
    }

    // =========================================================================
    // Property 4: sanitizePayload() always produces PII-free output
    // =========================================================================

    /**
     * **Validates: Requirements 4.5, 10.4**
     *
     * Property: For all payloads (even those injected with PII),
     * sanitizePayload() output never contains PII.
     *
     * @dataProvider piiInjectedPayloadProvider
     */
    public function testSanitizePayloadAlwaysRemovesPII(array $dirtyPayload): void
    {
        $config = array('tenant_id' => 'test-tenant', 'cloud_base_url' => 'https://cloud.nextlib.id');
        $exporter = new AggregateExporter($this->db, $this->httpClient, $config);

        $sanitized = $exporter->sanitizePayload($dirtyPayload);

        $this->assertFalse(
            AggregateExporter::containsPII($sanitized),
            sprintf(
                "sanitizePayload() did not remove all PII. Input: %s, Output: %s",
                json_encode($dirtyPayload),
                json_encode($sanitized)
            )
        );
    }

