    // =========================================================================
    // Property 4: containsPII() catches all known PII patterns
    // =========================================================================

    /**
     * **Validates: Requirements 4.5, 10.4**
     *
     * Property: containsPII() detects injected PII values (emails, phone
     * numbers, names, NIMs) reliably across all sample data.
     *
     * @dataProvider knownPiiDataProvider
     */
    public function testContainsPIIDetectsAllKnownPatterns(string $piiValue, string $piiType): void
    {
        $payload = array('field' => $piiValue);

        $this->assertTrue(
            AggregateExporter::containsPII($payload),
            sprintf(
                "containsPII() failed to detect %s: '%s'",
                $piiType,
                $piiValue
            )
        );
    }

    /**
     * Data provider with all known PII patterns that must be detected.
     *
     * @return array[]
     */
    public function knownPiiDataProvider(): array
    {
        $cases = array();

        foreach (self::PII_EMAILS as $i => $email) {
            $cases["email_$i"] = array($email, 'email');
        }

        foreach (self::PII_PHONES as $i => $phone) {
            $cases["phone_$i"] = array($phone, 'phone');
        }

        foreach (self::PII_NAMES as $i => $name) {
            $cases["name_$i"] = array($name, 'name (4+ words)');
        }

        foreach (self::PII_NIMS as $i => $nim) {
            $cases["nim_$i"] = array($nim, 'NIM/student ID');
        }

        return $cases;
    }

    // =========================================================================
    // Property 4: sanitizePayload() strips fields not in allowed list
    // =========================================================================

    /**
     * **Validates: Requirements 4.5, 10.4**
     *
     * Property: For all payloads with random extra keys, sanitizePayload()
     * output only contains keys from the allowed list.
     *
     * @dataProvider randomExtraFieldsProvider
     */
    public function testSanitizePayloadStripsNonAllowedFields(array $extraFields): void
    {
        $config = array('tenant_id' => 'test-tenant', 'cloud_base_url' => 'https://cloud.nextlib.id');
        $exporter = new AggregateExporter($this->db, $this->httpClient, $config);

        $payload = array_merge(
            array(
                'tenant_id' => 'valid-uuid',
                'date' => '2026-06-12',
                'stats' => array('visitor_count' => 10, 'loan_count' => 5, 'return_count' => 3),
                'sent_at' => '2026-06-12T23:59:00+07:00',
            ),
            $extraFields
        );

        $sanitized = $exporter->sanitizePayload($payload);

        $allowedTopKeys = array('tenant_id', 'date', 'stats', 'sent_at');
        $allowedStatsKeys = array('visitor_count', 'loan_count', 'return_count');

        // Verify only allowed top-level keys remain
        foreach (array_keys($sanitized) as $key) {
            $this->assertContains(
                $key,
                $allowedTopKeys,
                "Unexpected key '$key' found in sanitized payload. Extra fields: " . json_encode($extraFields)
            );
        }

        // Verify only allowed stats keys remain
        if (isset($sanitized['stats']) && is_array($sanitized['stats'])) {
            foreach (array_keys($sanitized['stats']) as $key) {
                $this->assertContains(
                    $key,
                    $allowedStatsKeys,
                    "Unexpected stats key '$key' found in sanitized payload."
                );
            }
        }
    }

    /**
     * Data provider that generates random extra field combinations.
     *
     * @return array[]
     */
    public function randomExtraFieldsProvider(): array
    {
        $cases = array();

        $extraKeyPool = array(
            'member_name', 'email', 'phone', 'nim', 'address',
            'borrowing_history', 'full_name', 'student_id',
            'ip_address', 'password', 'ssn', 'credit_card',
            'mother_maiden_name', 'date_of_birth', 'home_address',
        );

        $extraValuePool = array(
            'student@example.com',
            '+6281234567890',
            'Muhammad Rizky Pratama Putra',
            '20210001234',
            'Jl. Merdeka No. 123 RT01/RW02',
            array('book1', 'book2', 'book3'),
            true,
            12345,
            null,
        );

        for ($i = 0; $i < self::ITERATIONS; $i++) {
            $numExtras = mt_rand(1, 5);
            $extra = array();
            for ($j = 0; $j < $numExtras; $j++) {
                $key = $extraKeyPool[array_rand($extraKeyPool)];
                $value = $extraValuePool[array_rand($extraValuePool)];
