        return $cases;
    }

    // =========================================================================
    // Property 4: Full pipeline (buildPayload → sanitizePayload) produces no PII
    // =========================================================================

    /**
     * **Validates: Requirements 4.5, 10.4**
     *
     * Property: The complete export pipeline (collectDailyStats → buildPayload
     * → sanitizePayload) never produces output containing PII, regardless of
     * what PII data exists in the database.
     */
    public function testFullPipelineNeverLeaksPIIFromDatabase(): void
    {
        $config = array('tenant_id' => 'campus-uuid-abc', 'cloud_base_url' => 'https://cloud.nextlib.id');
        $exporter = new AggregateExporter($this->db, $this->httpClient, $config);

        // Insert visitors with PII in the database (names, member IDs)
        $piiNames = array(
            'Muhammad Rizky Pratama Putra',
            'Siti Nurhaliza Binti Ahmad',
            'John William Smith Junior',
        );

        $piiMemberIds = array('20210001234', '19850012345', '2024567890123');

        $today = date('Y-m-d');
        foreach ($piiNames as $i => $name) {
            $stmt = $this->db->prepare(
                "INSERT INTO visitor_count (member_id, member_name, checkin_date) VALUES (:mid, :name, :date)"
            );
            $stmt->execute(array(
                'mid' => $piiMemberIds[$i],
                'name' => $name,
                'date' => $today . ' 0' . $i . ':00:00',
            ));
        }

        // Insert loans with PII member_ids
        foreach ($piiMemberIds as $mid) {
            $stmt = $this->db->prepare(
                "INSERT INTO loan (member_id, item_code, loan_date, due_date) VALUES (:mid, :item, :loan, :due)"
            );
            $stmt->execute(array(
                'mid' => $mid,
                'item' => 'B' . mt_rand(10000, 99999),
                'loan' => $today,
                'due' => date('Y-m-d', strtotime('+14 days')),
            ));
        }

        // Run the full pipeline
        $stats = $exporter->collectDailyStats($today);
        $payload = $exporter->buildPayload($stats, $today);
        $sanitized = $exporter->sanitizePayload($payload);

        // Verify no PII leaked
        $this->assertFalse(
            AggregateExporter::containsPII($sanitized),
            "Full pipeline leaked PII from database. Output: " . json_encode($sanitized)
        );

        // Also verify the raw buildPayload output has no PII
        $this->assertFalse(
            AggregateExporter::containsPII($payload),
            "buildPayload() leaked PII from database. Output: " . json_encode($payload)
        );

        // Verify PII names do NOT appear in the JSON output
        $jsonOutput = json_encode($sanitized);
        foreach ($piiNames as $name) {
            $this->assertStringNotContainsString(
                $name,
                $jsonOutput,
                "PII name '$name' leaked into sanitized payload"
            );
        }

        foreach ($piiMemberIds as $mid) {
            $this->assertStringNotContainsString(
                $mid,
                $jsonOutput,
                "PII member_id '$mid' leaked into sanitized payload"
            );
        }
    }

    /**
     * **Validates: Requirements 4.5, 10.4**
     *
     * Property: For many random database states with PII, the pipeline
     * never produces PII in the output.
     */
    public function testPipelineWithRandomDatabaseStateNeverLeaksPII(): void
    {
        $config = array('tenant_id' => 'random-tenant', 'cloud_base_url' => 'https://cloud.nextlib.id');
        $exporter = new AggregateExporter($this->db, $this->httpClient, $config);

        $today = date('Y-m-d');

        // Run multiple iterations with random PII data in the database
        for ($iter = 0; $iter < 20; $iter++) {
            // Insert random number of visitors with PII names
            $numVisitors = mt_rand(0, 50);
            for ($i = 0; $i < $numVisitors; $i++) {
                $name = $this->generateRandomPIIName();
                $mid = $this->generateRandomNIM();
                $stmt = $this->db->prepare(
                    "INSERT INTO visitor_count (member_id, member_name, checkin_date) VALUES (:mid, :name, :date)"
                );
                $stmt->execute(array(
                    'mid' => $mid,
                    'name' => $name,
                    'date' => $today . ' ' . sprintf('%02d', mt_rand(0, 23)) . ':00:00',
                ));
            }

            // Insert random loans
            $numLoans = mt_rand(0, 30);
            for ($i = 0; $i < $numLoans; $i++) {
                $stmt = $this->db->prepare(
                    "INSERT INTO loan (member_id, item_code, loan_date, due_date) VALUES (:mid, :item, :loan, :due)"
                );
                $stmt->execute(array(
                    'mid' => $this->generateRandomNIM(),
                    'item' => 'B' . mt_rand(10000, 99999),
                    'loan' => $today,
                    'due' => date('Y-m-d', strtotime('+14 days')),
                ));
            }

            // Run pipeline
            $stats = $exporter->collectDailyStats($today);
            $payload = $exporter->buildPayload($stats, $today);
            $sanitized = $exporter->sanitizePayload($payload);

            $this->assertFalse(
                AggregateExporter::containsPII($sanitized),
                "Iteration $iter: Pipeline leaked PII. Output: " . json_encode($sanitized)
            );
        }
    }

    // =========================================================================
    // Helper methods for generating random test data
    // =========================================================================

    /**
     * Generate an array of tenant IDs in various formats (UUIDs, slugs).
     *
     * @return string[]
     */
    private function generateTenantIds(): array
    {
        $ids = array();

        // UUID format
        for ($i = 0; $i < 20; $i++) {
            $ids[] = sprintf(
                '%04x%04x-%04x-%04x-%04x-%04x%04x%04x',
                mt_rand(0, 0xffff), mt_rand(0, 0xffff),
                mt_rand(0, 0xffff),
                mt_rand(0, 0x0fff) | 0x4000,
                mt_rand(0, 0x3fff) | 0x8000,
                mt_rand(0, 0xffff), mt_rand(0, 0xffff), mt_rand(0, 0xffff)
            );
        }

        // Slug format
        $slugPrefixes = array('univ', 'campus', 'lib', 'inst', 'polytechnic');
        $slugSuffixes = array('jakarta', 'bandung', 'surabaya', 'yogya', 'medan');
        for ($i = 0; $i < 10; $i++) {
            $ids[] = $slugPrefixes[array_rand($slugPrefixes)] . '-' . $slugSuffixes[array_rand($slugSuffixes)] . '-' . mt_rand(1, 99);
        }

        // Short IDs
        for ($i = 0; $i < 5; $i++) {
            $ids[] = 'tenant-' . mt_rand(1, 9999);
        }

        return $ids;
    }

    /**
     * Generate an array of dates in various formats.
     *
     * @return string[]
     */
    private function generateDates(): array
    {
        $dates = array();

        // Current/recent dates
        for ($i = 0; $i < 15; $i++) {
            $offset = mt_rand(0, 365);
            $dates[] = date('Y-m-d', strtotime("-$offset days"));
        }

        // Edge dates
        $dates[] = '2020-01-01';
        $dates[] = '2025-12-31';
        $dates[] = '2026-02-28';
        $dates[] = '2024-02-29'; // Leap year
        $dates[] = '2030-06-15';

        return $dates;
    }

    /**
     * Generate a random PII-like name (4+ words).
     *
     * @return string
     */
    private function generateRandomPIIName(): string
    {
        $firstNames = array('Muhammad', 'Siti', 'John', 'Maria', 'Budi', 'Ahmad', 'Dewi', 'Andi');
        $middleNames = array('Rizky', 'Nur', 'William', 'Christina', 'Putra', 'Bin', 'Sri', 'Dwi');
        $lastNames = array('Pratama', 'Haliza', 'Smith', 'Sartika', 'Setiawan', 'Rahman', 'Wati', 'Kurniawan');
        $suffixes = array('Putra', 'Junior', 'Utama', 'Nusantara', 'Sakti', 'Jaya', 'Mandiri', 'Sejahtera');

        return $firstNames[array_rand($firstNames)] . ' '
            . $middleNames[array_rand($middleNames)] . ' '
            . $lastNames[array_rand($lastNames)] . ' '
            . $suffixes[array_rand($suffixes)];
    }

    /**
     * Generate a random NIM/student ID (8+ digits).
     *
     * @return string
     */
    private function generateRandomNIM(): string
    {
        $year = mt_rand(2015, 2026);
        $dept = mt_rand(10, 99);
        $seq = mt_rand(1000, 9999);
        return $year . $dept . $seq;
    }

    // =========================================================================
    // Property 13: PII Sanitization Completeness — EnhancedExporter
    // =========================================================================

    /**
     * Create a minimal EnhancedExporter instance for PII sanitization tests.
     * Uses in-memory SQLite with all required SLiMS tables.
     *
     * @return EnhancedExporter
     */
    private function createEnhancedExporter(): EnhancedExporter
    {
        // EnhancedExporter needs a DB with all SLiMS tables for MetricsCollector/AnomalyTagger
        $db = new PDO('sqlite::memory:');
        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        $db->exec("CREATE TABLE visitor_count (id INTEGER PRIMARY KEY, member_id INTEGER, checkin_date DATETIME)");
        $db->exec("CREATE TABLE loan (loan_id INTEGER PRIMARY KEY, member_id INTEGER, loan_date DATE, return_date DATE, due_date DATE, is_lent INTEGER DEFAULT 1, is_return INTEGER DEFAULT 0)");
        $db->exec("CREATE TABLE member (member_id INTEGER PRIMARY KEY, register_date DATE, expire_date DATE)");
        $db->exec("CREATE TABLE biblio (biblio_id INTEGER PRIMARY KEY, input_date DATE)");
        $db->exec("CREATE TABLE item (item_id INTEGER PRIMARY KEY, input_date DATE)");
        $db->exec("CREATE TABLE fines (fines_id INTEGER PRIMARY KEY, fines_date DATE, debet INTEGER DEFAULT 0, credit INTEGER DEFAULT 0)");
        $db->exec("CREATE TABLE reserve (reserve_id INTEGER PRIMARY KEY, reserve_date DATE)");

        $tempDir = sys_get_temp_dir() . '/pii_prop_test_' . getmypid() . '_' . mt_rand();
        mkdir($tempDir, 0755, true);

        $collector     = new MetricsCollector($db);
        $anomalyTagger = new AnomalyTagger($db, $collector);
        $retryScheduler = new RetryScheduler($tempDir);
        $httpClient    = $this->createMock(HttpClient::class);

        $config = array(
            'tenant_id'      => 'test-tenant-uuid',
            'cloud_base_url' => 'https://cloud.nextlib.test',
            'api_secret'     => 'test-secret-key',
            'v2_enabled'     => false,
            'export_schedule' => 'daily',
        );

        return new EnhancedExporter(
            $collector,
            $anomalyTagger,
            $retryScheduler,
            $httpClient,
            $config,
            $tempDir
        );
    }

    /**
     * Generate random PII values to inject into payloads.
     * Returns an array of [fieldKey => piiValue] pairs.
     *
     * @return array
     */
    private function generateRandomPIIInjection(): array
    {
        $piiPool = array(
            // Emails
            array('injected_email', 'student@university.ac.id'),
            array('injected_email', 'john.doe@gmail.com'),
            array('injected_email', 'budi.santoso@campus.ac.id'),
            array('injected_email', 'admin@univ.edu'),
            array('injected_email', 'test+user@example.co.id'),
            // Phones
            array('injected_phone', '+6281234567890'),
            array('injected_phone', '08123456789'),
            array('injected_phone', '0812 3456 7890'),
            array('injected_phone', '+62-812-3456-7890'),
            array('injected_phone', '021-555-12345'),
            // NIMs (8+ consecutive digits)
            array('injected_nim', '20210001234'),
            array('injected_nim', '19850012345'),
            array('injected_nim', '2024567890123'),
            array('injected_nim', '12345678'),
            array('injected_nim', '20200099887'),
            // Multi-word names (>3 words)
            array('injected_name', 'Muhammad Rizky Pratama Putra'),
            array('injected_name', 'Siti Nurhaliza Binti Ahmad'),
            array('injected_name', 'John William Smith Junior'),
            array('injected_name', 'Maria Christina Dewi Sartika'),
            array('injected_name', 'Budi Setiawan Putra Utama'),
        );

        return $piiPool[array_rand($piiPool)];
    }

    /**
     * Feature: enhanced-agent-exporter, Property 13: PII Sanitization Completeness
     *
     * **Validates: Requirements 10.1, 10.3**
     *
     * Property 13: For random v1 payloads with injected PII patterns (emails,
     * phone numbers, NIM-like sequences, multi-word names), sanitizePayloadV1()
     * removes all PII — containsPII() returns false on the result.
     *
     * Minimum 100 iterations.
     */
    public function testEnhancedExporterSanitizeV1AlwaysRemovesPII(): void
    {
        $exporter = $this->createEnhancedExporter();

        $piiFields = array(
            // Emails
            'student@university.ac.id',
            'john.doe@gmail.com',
            'admin@univ.edu',
            'budi.santoso@campus.ac.id',
            'test+user@example.co.id',
            // Phones
            '+6281234567890',
            '08123456789',
            '0812 3456 7890',
            '+62-812-3456-7890',
            '021-555-12345',
            // NIMs
            '20210001234',
            '19850012345',
            '2024567890123',
            '12345678',
            '20200099887',
            // Names (>3 words)
            'Muhammad Rizky Pratama Putra',
            'Siti Nurhaliza Binti Ahmad',
            'John William Smith Junior',
            'Maria Christina Dewi Sartika',
            'Budi Setiawan Putra Utama',
        );

        $injectableTopLevelKeys = array('tenant_id', 'extra_field', 'member_name', 'email', 'phone', 'nim');
        $dates = $this->generateDates();

        for ($i = 0; $i < self::ITERATIONS; $i++) {
            $piiValue = $piiFields[array_rand($piiFields)];
            // Inject into tenant_id (most direct injection) and optionally an extra key
            $injectKey = $injectableTopLevelKeys[array_rand($injectableTopLevelKeys)];

            $dirtyPayload = array(
                'tenant_id' => ($injectKey === 'tenant_id') ? $piiValue : 'tenant-' . mt_rand(1, 9999),
                'date'      => $dates[array_rand($dates)],
                'stats'     => array(
                    'visitor_count' => mt_rand(0, 10000),
                    'loan_count'    => mt_rand(0, 10000),
                    'return_count'  => mt_rand(0, 10000),
                ),
                'sent_at'   => date('c'),
            );

            // Always inject PII in an extra field too (will be stripped as non-allowed key)
            if ($injectKey !== 'tenant_id') {
                $dirtyPayload[$injectKey] = $piiValue;
            }

            $sanitized = $exporter->sanitizePayloadV1($dirtyPayload);

            $this->assertFalse(
                EnhancedExporter::containsPII($sanitized),
                sprintf(
                    'Iteration %d: sanitizePayloadV1() did not remove PII. ' .
                    'Injected \'%s\' => \'%s\'. Input: %s, Output: %s',
                    $i,
                    $injectKey,
                    $piiValue,
                    json_encode($dirtyPayload),
                    json_encode($sanitized)
                )
            );
        }
    }

    /**
     * Feature: enhanced-agent-exporter, Property 13: PII Sanitization Completeness
     *
     * **Validates: Requirements 10.1, 10.3**
     *
     * Property 13: For random v2 payloads with injected PII patterns (emails,
     * phone numbers, NIM-like sequences, multi-word names), sanitizePayloadV2()
     * removes all PII — containsPII() returns false on the result.
     *
     * Minimum 100 iterations.
     */
    public function testEnhancedExporterSanitizeV2AlwaysRemovesPII(): void
    {
        $exporter = $this->createEnhancedExporter();

        $piiFields = array(
            // Emails
            'student@university.ac.id',
            'john.doe@gmail.com',
            'admin@univ.edu',
            'budi.santoso@campus.ac.id',
            'test+user@example.co.id',
            // Phones
            '+6281234567890',
            '08123456789',
            '0812 3456 7890',
            '+62-812-3456-7890',
            '021-555-12345',
            // NIMs
            '20210001234',
            '19850012345',
            '2024567890123',
            '12345678',
            '20200099887',
            // Names (>3 words)
            'Muhammad Rizky Pratama Putra',
            'Siti Nurhaliza Binti Ahmad',
            'John William Smith Junior',
            'Maria Christina Dewi Sartika',
            'Budi Setiawan Putra Utama',
        );

        $injectableTopLevelKeys = array('tenant_id', 'extra_field', 'member_name', 'email', 'phone', 'nim', 'schema_version');
        $dates = $this->generateDates();

        $dailyMetricKeys = array(
            'visitor_count', 'unique_visitor_count', 'loan_count', 'return_count',
            'new_member_count', 'new_biblio_count', 'new_item_count',
            'fines_debet_total', 'fines_credit_total', 'reservation_count',
        );
        $snapshotMetricKeys = array('total_collection_size', 'active_member_count', 'active_overdue_count');

        for ($i = 0; $i < self::ITERATIONS; $i++) {
            $piiValue = $piiFields[array_rand($piiFields)];
            $injectKey = $injectableTopLevelKeys[array_rand($injectableTopLevelKeys)];

            // Build base v2 payload with safe values
            $dailyMetrics = array();
            foreach ($dailyMetricKeys as $k) {
                $dailyMetrics[$k] = mt_rand(0, 10000);
            }
            $snapshotMetrics = array();
            foreach ($snapshotMetricKeys as $k) {
                $snapshotMetrics[$k] = mt_rand(0, 100000);
            }

            $dirtyPayload = array(
                'schema_version'   => '2.0',
                'tenant_id'        => 'tenant-' . mt_rand(1, 9999),
                'date'             => $dates[array_rand($dates)],
                'sent_at'          => date('c'),
                'daily_metrics'    => $dailyMetrics,
                'snapshot_metrics' => $snapshotMetrics,
                'anomaly_flags'    => array(),
            );

            // Inject PII into chosen field
            if ($injectKey === 'tenant_id') {
                $dirtyPayload['tenant_id'] = $piiValue;
            } elseif ($injectKey === 'schema_version') {
                // Inject into schema_version (allowed key but should be sanitized if PII)
                $dirtyPayload['schema_version'] = $piiValue;
            } else {
                // Inject into a non-allowed key (will be stripped)
                $dirtyPayload[$injectKey] = $piiValue;
            }

            $sanitized = $exporter->sanitizePayloadV2($dirtyPayload);

            $this->assertFalse(
                EnhancedExporter::containsPII($sanitized),
                sprintf(
                    'Iteration %d: sanitizePayloadV2() did not remove PII. ' .
                    'Injected \'%s\' => \'%s\'. Input: %s, Output: %s',
                    $i,
                    $injectKey,
                    $piiValue,
                    json_encode($dirtyPayload),
                    json_encode($sanitized)
                )
            );
        }
    }
